// --- Sparse-CBOR write (ADR-0042 driver path). ---

// Marshal writes the SoA buffer to w as the sparse-CBOR wire
// format produced through factsschema/dml_cbor. Thin wrapper
// around KeelsonQueryRequestBuildEntities — the per-row chain lives there and
// works against any leeway-DML class that structurally satisfies
// KeelsonQueryRequestEntityI.
func (c *KeelsonQueryRequestColumns) Marshal(w io.Writer) (err error) {
	ent := keelsonQueryRequestPool.Get().(*cbdml.InEntityFacts)
	defer keelsonQueryRequestPool.Put(ent)
	ent.SetActiveSections(KeelsonQueryRequestActiveSections)
	ent.Builder().SetActiveFields(KeelsonQueryRequestActiveFields())
	err = KeelsonQueryRequestBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("keelsonqueryrequest: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("keelsonqueryrequest: marshal write: %w", err)
	}
	return
}

